with metrics as (select *, min(sqft) over (partition by city order by sqft, id rows between unbounded preceding and current row) running_min_sqft, sum(sqft) over (partition by city order by sqft, id rows between unbounded preceding and current row) running_sum_sqft, max(sqft) over (partition by city order by sqft, id rows between unbounded preceding and current row) running_max_sqft, lag(sqft, 2) over (partition by city order by sqft, id) prev_sqft from stores) select case when running_min_sqft >= 15400 then 'LARGE' else 'SMALL' end as running_min_sqft_tier, case when prev_sqft >= 14447 then 'HIGH' else 'LOW' end as prev_sqft_tier, size(collect_set(city)) as num_cities, count(*) filter (where city = 'Tokyo') as tokyo_rows from metrics group by cube (case when running_min_sqft >= 15400 then 'LARGE' else 'SMALL' end, case when prev_sqft >= 14447 then 'HIGH' else 'LOW' end) having count(*) filter (where city = 'Tokyo') < 1000;
